{"path": "/var/folders/bd/8xxg4c4j4rqc_6fqwvpxwnd80000gn/T/hackprobe_k1flfm0e/ep5/solution.py", "content": "import sys

MOD = 10**9 + 7

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    results = []
    # Precompute DP table
    # dp[n][k] = number of particles
    max_n = 1005
    max_k = 1005
    dp = [[0] * (max_k) for _ in range(max_n)]

    # Base cases
    for i in range(max_n):
        dp[i][1] = 1  # decay age 1 produces no copies
    for j in range(max_k):
        dp[0][j] = 1  # no planes, just the original particle

    for n in range(1, max_n):
        for k in range(2, max_k):
            # Recurrence: f(n,k) = f(n-1,k) + f(n,k-1)
            dp[n][k] = (dp[n-1][k] + dp[n][k-1]) % MOD

    for _ in range(t):
        n = int(next(it))
        k = int(next(it))
        results.append(dp[n][k] % MOD)

    for r in results:
        print(r)

if __name__ == "__main__":
    solve()
"}

